def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value: datetime.timedelta instance
    :return: int number of seconds or None if input is missing or invalid
    """
    if value is None:
        return None
    try:
        # Convert to total seconds as an integer
        return int(value.total_seconds())
    except Exception:
        return None

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: value to dehydrate
    :type value: datetime.time
    :return: ISO-8601 string representation of the time, or None if value is None
    """
    if value is None:
        return None
    try:
        return value.isoformat()
    except Exception as exc:
        raise TypeError("value must be a datetime.time instance") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if value is None:
        return None
    try:
        time_val = value.time.isoformat()
    except AttributeError:
        # if time is already a string or not a datetime, keep it as is
        time_val = value.time
    return {
        'lat': getattr(value, 'lat', None),
        'lon': getattr(value, 'lon', None),
        'time': time_val
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Try to return keys from a dedicated dictionary attribute if it exists
        if hasattr(self, "_data") and isinstance(self._data, dict):
            return list(self._data.keys())
        # Fallback: use instance dictionary excluding private attributes
        data = getattr(self, "__dict__", {})
        return [k for k in data if not k.startswith("_")]
    except Exception:
        # In case of unexpected errors, return an empty list
        return []

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # If a pre-built lookup exists, use it for O(1) access
    if hasattr(self, "index_lookup") and key in self.index_lookup:
        return self.index_lookup[key]
    # Fall back to searching a list of keys if available
    if hasattr(self, "_index"):
        try:
            return self._index.index(key)
        except ValueError:
            pass
    # If the key was not found, raise a KeyError
    raise KeyError(f"Key {key!r} not found")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the internal storage; use _items if present, else fall back to dict-like interface
    if hasattr(self, "_items"):
        data = self._items
    elif isinstance(self, dict):
        data = self
    else:
        # Try to iterate over self if it behaves like a collection
        try:
            data = list(self)
        except Exception:
            raise AttributeError("Object does not expose a suitable collection of items")

    # No filtering -> return all values
    if not keys:
        all_values = []
        for item in data:
            if isinstance(item, dict):
                all_values.extend(item.values())
            else:
                all_values.append(item)
        return all_values

    # Collect specified keys or indices
    result = []
    for k in keys:
        if isinstance(k, int):
            try:
                result.append(data[k])
            except (IndexError, TypeError) as exc:
                raise IndexError(f"Index {k} out of range") from exc
        else:
            for item in data:
                if isinstance(item, dict) and k in item:
                    result.append(item[k])
                # allow attribute access for objects that are not dicts
                elif not isinstance(item, dict):
                    try:
                        result.append(getattr(item, k))
                    except AttributeError:
                        pass
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    buf_attr = None
    buf = None
    # Find a suitable buffer attribute
    for name in ("buffer", "data", "bytes"):
        if hasattr(self, name):
            buf_attr = name
            buf = getattr(self, name)
            break
    if buf_attr is None or buf is None:
        raise AttributeError("No buffer attribute found on the object")
    if len(buf) < 2:
        raise ValueError("Not enough data to pop u16")
    last_two = buf[-2:]
    if isinstance(buf, bytearray):
        # Modify in place
        del buf[-2:]
    else:
        # For immutable types like bytes, replace the attribute
        setattr(self, buf_attr, buf[:-2])
    return int.from_bytes(last_two, "big")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Basic validation for the class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")
    # Ensure srid_map is a mapping
    if not hasattr(srid_map, "items"):
        raise TypeError("srid_map must be a mapping type")

    # Prepare namespace and annotations for the new class
    namespace = {}
    annotations = {}
    seen = set()
    field_names = []

    for item in fields:
        if isinstance(item, str):
            field_name = item
            field_type = 'typing.Any'
        elif isinstance(item, tuple) and len(item) == 2:
            field_name, field_type = item
        else:
            raise TypeError(f"Invalid field specification: {item!r}")

        if not isinstance(field_name, str) or not field_name.isidentifier():
            raise TypeError(f"Field name must be a valid identifier, got {field_name!r}")
        if field_name in seen:
            raise TypeError(f"Duplicate field name: {field_name!r}")
        seen.add(field_name)
        field_names.append(field_name)
        annotations[field_name] = field_type

    namespace['__annotations__'] = annotations
    namespace['_srid_map'] = srid_map

    # Define a simple __init__ that assigns provided values to fields
    def __init__(self, *args, **kwargs):
        if len(args) + len(kwargs) < len(field_names):
            raise TypeError(
                f"{name} expected at least {len(field_names)} arguments"
            )
        for i, key in enumerate(field_names):
            if key in kwargs:
                value = kwargs[key]
            else:
                try:
                    value = args[i]
                except IndexError:
                    value = None
            setattr(self, key, value)

    namespace['__init__'] = __init__

    # Attempt to use an existing Point base class; fall back to object
    try:
        base_cls = Point  # assume Point is defined elsewhere
    except NameError:
        base_cls = object

    return type(name, (base_cls,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""

    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")

    parts = s.strip().split(".")
    if not parts or parts == [""]:
        return ()

    parsed: list[int] = []
    for part in parts:
        if part == "":
            parsed.append(0)
            continue
        try:
            parsed.append(int(part))
        except ValueError:
            # Try to extract a leading integer from the part
            digits = ""
            for ch in part:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if digits:
                parsed.append(int(digits))
            else:
                raise ValueError(f"Non-numeric version part: {part!r}") from None
    return tuple(parsed)

