                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)

    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        if maxsize <= 0:
            # Never cache, just forward calls
            @wraps(func)
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        cache = OrderedDict()

        def make_key(args, kwargs):
            # Build a hashable key from positional and keyword arguments.
            key = args
            if kwargs:
                for k in sorted(kwargs):
                    key += (k, kwargs[k])
            if typed:
                key += tuple(type(v) for v in args)
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            now = timer()
            if key in cache:
                result, timestamp = cache[key]
                if now - timestamp < ttl:
                    # Refresh key order to denote recent access
                    cache.move_to_end(key)
                    return result
                # TTL expired; remove entry
                del cache[key]

            # Call the original function and store its result with current timestamp
            result = func(*args, **kwargs)
            cache[key] = (result, now)

            # Enforce maxsize and LRU eviction policy
            if len(cache) > maxsize:
                cache.popitem(last=False)

            return result

        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize is None or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer or None")

    def make_key(args, kwargs):
        # Sort kwargs to make key deterministic
        kw_items = tuple(sorted(kwargs.items()))
        if typed:
            types = tuple(type(arg) for arg in args) + tuple(type(v) for _, v in kw_items)
            return (args, kw_items, types)
        else:
            return (args, kw_items)

    def decorator(fn):
        cache = {}  # key -> (value, count)
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                value, count = cache[key]
                # increment usage count
                cache[key] = (value, count + 1)
                return value
            result = fn(*args, **kwargs)
            if maxsize is not None and len(cache) >= maxsize:
                # Evict the least frequently used entry
                # Find key with minimal count
                # In case of ties, evict arbitrary one
                min_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        min_key = k
                if min_key is not None:
                    del cache[min_key]
            cache[key] = (result, 1)
            return result
        return wrapper
    # Support usage as @lfu_cache(...) or @lfu_cache
    return decorator

def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        node = self._head[2]
        if node is self._tail:
            raise KeyError('list is empty')
        self._find_lt(node[0])
        self._remove(node)
        return (node[0], node[1])

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    storage = self.storage

    if key in storage:
        return storage[key]
    else:
        storage[key] = default
        try:
            storage._p_changed = True
        except Exception:
            pass
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(method):
        @wraps(method)
        def wrapper(self, *args, **kwargs):
            c = cache(self)
            if c is None:
                return method(self, *args, **kwargs)
            k = key(*args, **kwargs)
            try:
                if lock:
                    with lock(self):
                        return c[k]
                else:
                    return c[k]
            except KeyError:
                pass
            v = method(self, *args, **kwargs)
            try:
                if lock:
                    with lock(self):
                        c[k] = v
                else:
                    c[k] = v
            except ValueError:
                pass
            return v
        return wrapper
    return decorator

