def _reset_logging(cls):
    """Reset"""
    try:
        import logging
        root = logging.getLogger()
        # Remove and close existing handlers
        for handler in root.handlers[:]:
            try:
                handler.flush()
                handler.close()
            except Exception:
                # Ignore any errors while cleaning up handlers
                pass
            root.removeHandler(handler)
        # Reset the log level to the default (WARNING)
        root.setLevel(logging.WARNING)
        # Add a default stream handler if none exist
        if not root.handlers:
            root.addHandler(logging.StreamHandler())
    except Exception:
        # Swallow any errors to avoid impacting application flow
        pass

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    cls_name = self.__class__.__name__
    for suffix in ('Py', 'Fallback'):
        if cls_name.endswith(suffix):
            return cls_name[:-len(suffix)]
    return cls_name

