def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate input is a sequence
    if not isinstance(classes, (list, tuple, set)):
        raise TypeError("classes must be an iterable of class objects")
    # Validate each element is a class
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"item {c!r} is not a class")
    # Preserve order, avoid duplicates
    seen = set()
    minimal = []
    for c in classes:
        if c in seen:
            continue
        seen.add(c)
        # If any other class in the input is a subclass of c, c is redundant
        if any(issubclass(d, c) and d is not c for d in classes):
            continue
        minimal.append(c)
    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Collect classes to inspect
    classes_to_inspect = [self.__class__]
    if all:
        # Include ancestor classes (excluding the base object class)
        classes_to_inspect = list(self.__class__.__mro__)
        if object in classes_to_inspect:
            classes_to_inspect.remove(object)

    # Accumulate attribute information
    attrs = {}
    for cls in classes_to_inspect:
        # Use reverse order so that subclasses override base definitions
        for name, obj in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(obj):
                continue
            # Avoid re-adding an attribute that has already been defined in a subclass
            if name in attrs:
                continue
            # Determine a description: prefer a 'description' attribute, then docstring
            desc = None
            if hasattr(obj, "description"):
                desc = getattr(obj, "description")
            elif hasattr(obj, "__doc__"):
                desc = getattr(obj, "__doc__")
            if desc is None:
                desc = ""
            attrs[name] = desc
    return attrs

def reset(self):
        """ Reset the histogram.  
        Current context is reset to an empty dict.  
        Bins are reinitialized with the *initial_value* or with *make_bins()* (depending on the initialization).  
        """
        # Reset the context dictionary.
        self.context = {}

        try:
            # Prefer reusing the existing bin count if possible.
            bin_count = getattr(self, "num_bins", len(getattr(self, "bins", [])))

            # If an initial value is defined, fill all bins with it.
            init_val = getattr(self, "initial_value", None)
            if init_val is not None:
                self.bins = [init_val for _ in range(bin_count)]
            # Otherwise, if a make_bins method exists, use it to create bins.
            elif hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            # Fallback to an empty list of bins if nothing is specified.
            else:
                self.bins = []

            # Reset any bookkeeping counters that might exist.
            if hasattr(self, "total_count"):
                self.total_count = 0

        except Exception as exc:
            raise RuntimeError(f"Failed to reset histogram: {exc}") from exc.

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    if separator is None:
        raise ValueError("separator must be a string")

    # Write header if provided
    if header is not None:
        try:
            print(header)
        except Exception as exc:
            raise RuntimeError(f"Failed to write header: {exc}") from exc

    for point in self:
        # Try to get coordinate and value attributes; fall back to tuple unpacking
        coordinate = getattr(point, "coordinate", None)
        value = getattr(point, "value", None)
        if coordinate is None or value is None:
            try:
                coordinate, value = point
            except Exception as exc:
                raise RuntimeError(f"Point {point!r} is not iterable and has no attributes") from exc

        # Convert coordinate parts to string
        coord_parts = []
        if isinstance(coordinate, (list, tuple)):
            for c in coordinate:
                coord_parts.append(str(c))
        else:
            coord_parts.append(str(coordinate))

        # Convert value parts to string
        value_parts = []
        if isinstance(value, (list, tuple)):
            for v in value:
                value_parts.append(str(v))
        else:
            if isinstance(value, str):
                value_parts.append(value)
            elif value is None:
                value_parts.append("")
            else:
                value_parts.append(str(value))

        # Join all parts with the separator and output the line
        line = separator.join(coord_parts + value_parts)
        print(line)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Verify that we have variables to search
    if not hasattr(self, "_variables") or not isinstance(self._variables, dict):
        raise AttributeError("The caller does not have a '_variables' dictionary to search.")
    err_indices = []

    # Scan through all variables looking for those that match the coordinate name
    # and conventionally indicate an error (e.g., ending with '_err' or containing the
    # coordinate name followed by 'err').
    for var_name, var in self._variables.items():
        # Check naming patterns
        if coord_name in var_name and (var_name.endswith("_err") or var_name.lower().endswith("err")):
            err_indices.append(var_name)

        # If the variable object carries coordinate information we also check that
        # the requested coordinate is part of its coordinate list.
        if hasattr(var, "coords"):
            try:
                coords = var.coords
                # Normalise to a list or tuple
                if isinstance(coords, dict):
                    coord_keys = list(coords.keys())
                else:
                    coord_keys = list(coords)
                if coord_name in coord_keys:
                    # Byte or boolean arrays typically come with an accompanying
                    # coordinate; treat them as errors if they are 1‑D.
                    if getattr(var, "dtype", None) is not None and var.dtype.kind == "b" and var.ndim == 1:
                        err_indices.append(var_name)
            except Exception:
                # Ignore any errors in accessing coordinate information
                pass

    if not err_indices:
        raise KeyError(f"No error indices found for coordinate '{coord_name}'.")
    return err_indices

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        # Exclude source sequences
        if isinstance(seq, Source):
            return False
        # Directly a single FillRequest instance
        if isinstance(seq, FillRequest):
            return True
        # Handle common built-in sequence types
        if isinstance(seq, (list, tuple, set, frozenset)):
            return any(isinstance(item, FillRequest) for item in seq)
        # General iterable fallback
        return any(isinstance(item, FillRequest) for item in seq)
    except Exception:
        return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        fill_method = getattr(obj, 'fill', None)
        request_method = getattr(obj, 'request', None)
        return callable(fill_method) and callable(request_method)
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        run_attr = getattr(obj, 'run', None)
    except Exception:
        return False
    return callable(run_attr)

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        fill = getattr(obj, 'fill', None)
        compute = getattr(obj, 'compute', None)
        return callable(fill) and callable(compute)
    except Exception:
        return False

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from django.core.exceptions import ValidationError

    # Define permitted regex patterns for keys and values.
    # The exact patterns can be modified to match the real application's requirements.
    KEY_REGEX = r'^[A-Za-z0-9_\-]+$'
    VALUE_REGEX = r'^[A-Za-z0-9_\-]+$'

    key_pattern = re.compile(KEY_REGEX)
    value_pattern = re.compile(VALUE_REGEX)

    errors = []

    for key, value in labels.items():
        # Validate the key.
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not key_pattern.match(key):
                errors.append(
                    {str(key): f"Label key '{key}' does not match the regex [{KEY_REGEX}]"}
                )

        # Validate the value.
        if isinstance(value, (list, tuple)):
            if not value:
                # Empty list is considered invalid: treat as non string item.
                errors.append({str(value): 'expected string or bytes-like object'})
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    if not value_pattern.match(item):
                        errors.append(
                            {str(item): f"Label value '{item}' does not match the regex [{VALUE_REGEX}]"}
                        )
        else:
            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_pattern.match(value):
                    errors.append(
                        {str(value): f"Label value '{value}' does not match the regex [{VALUE_REGEX}]"}
                    )

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure we have a spec and a manifest to work with
    spec = getattr(app, "spec", None)
    if spec is None:
        return
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        return

    # Retrieve the existing observers dictionary; create it if it doesn't exist
    observers = getattr(spec, "observers", None)
    if observers is None or not isinstance(observers, dict):
        observers = {}
    # Default schema template
    default_schema = {"type": "object"}
    # Determine the list of resources in the manifest
    try:
        # The manifest may be a dict containing an 'items' list, or it could be a list itself
        if isinstance(manifest, dict):
            resources = list(manifest.get("items", []))
        elif isinstance(manifest, (list, tuple)):
            resources = list(manifest)
        else:
            resources = []
    except Exception:
        resources = []

    # Generate default observer schemas for resources lacking one
    for resource in resources:
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        if kind not in observers:
            observers[kind] = default_schema

    # Assign the updated observers back to the spec
    try:
        setattr(spec, "observers", observers)
    except Exception:
        pass

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    status = getattr(self, 'status', None)
    if status is None:
        raise AttributeError(f"{self.__class__.__name__} instance has no 'status' attribute")
    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        # Primary attribute assumed to hold the log
        log = getattr(self, 'validation_log', None)
        if log is None:
            return prefix

        # If log is a string, just prepend prefix
        if isinstance(log, str):
            return f"{prefix}{log}"

        # Prepare lines from log
        lines = []

        # If it's a mapping, show key: value pairs
        if isinstance(log, dict):
            for key, value in log.items():
                lines.append(f"{key}: {value}")
        # If it's iterable (list, tuple, set), iterate directly
        elif hasattr(log, '__iter__'):
            for item in log:
                lines.append(str(item))
        else:
            # Fallback: convert to string
            lines.append(str(log))

        # Prefix each line if prefix is provided
        if prefix:
            lines = [f"{prefix}{line}" for line in lines]

        return "\n".join(lines)
    except Exception:
        # In any failure, return just the prefix
        return prefix

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dict")

    # Determine the spec version to use for validation
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_value = inventory.get("type")
        if isinstance(type_value, str):
            allowed = getattr(self, "allowed_spec_versions", None)
            if callable(allowed):
                allowed_set = set(allowed())
            else:
                allowed_set = set(getattr(self, "allowed_spec_versions", []))
            if type_value in allowed_set:
                spec_version = type_value

    # Run the validator for the determined spec version, if one exists.
    # If the validator raises an exception, wrap it in ValueError for clarity.
    try:
        validator_name = f"_validate_{spec_version}" if spec_version is not None else None
        validator = getattr(self, validator_name, None) if validator_name else None
        if validator:
            validator(inventory)
    except Exception as exc:
        raise ValueError(f"Inventory validation failed: {exc}") from exc

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used.

    Arguments:
        manifest_files: The collection of manifest entries. It can be a dict
            mapping filenames to digests, a list/tuple of mappings with a
            ``'digest'`` key, objects with a ``digest`` attribute, or a plain
            iterable of digest strings.
        digests_used: Iterable of digest strings that have been used.

    Raises:
        ValueError: If any digest required by the manifest is missing from
        ``digests_used``.
    """
    # Build a set of digests required by the manifest
    required_digests = set()
    # Handle dictionary mapping (filename -> digest)
    if isinstance(manifest_files, dict):
        for digest in manifest_files.values():
            if digest:
                required_digests.add(str(digest))
    else:
        # Handle iterable of digests or objects with a digest attribute
        for entry in manifest_files:
            if isinstance(entry, dict):
                digest = entry.get('digest')
                if digest:
                    required_digests.add(str(digest))
            elif hasattr(entry, 'digest'):
                required_digests.add(str(entry.digest))
            else:
                # Assume entry itself is the digest string
                required_digests.add(str(entry))

    # Normalise the digests_used input to a set of strings
    digests_used_set = {str(d) for d in digests_used}

    # Determine any required digests that are missing
    missing = required_digests - digests_used_set
    if missing:
        missing_str = ', '.join(sorted(missing))
        raise ValueError(f"Missing digests in manifest that are not used: {missing_str}")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    mapping = {}
    try:
        # inventory is expected to be a mapping from logical paths to some
        # representation of versioned files.  The exact format is not
        # guaranteed, so we try a few common patterns.
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a dictionary-like mapping")
        for logical_path, value in inventory.items():
            files = set()
            # Case 1: value is a dict mapping version -> files.
            if isinstance(value, dict):
                for ver_key, file_list in value.items():
                    if isinstance(file_list, (list, set, tuple)):
                        files.update(file_list)
                    else:
                        # single file entry
                        files.add(file_list)
            # Case 2: value is a list of entries, possibly tuples of
            # (file, version).  We ignore version in this fallback.
            elif isinstance(value, (list, set, tuple)):
                for entry in value:
                    if isinstance(entry, (tuple, list)) and len(entry) == 2:
                        files.add(entry[0])
                    else:
                        files.add(entry)
            else:
                # Any other single file representation
                files.add(value)
            mapping[logical_path] = files
    except Exception as exc:
        raise ValueError(
            f"Failed to build logical path map for version {version}: {exc}"
        ) from exc
    return mapping

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Require a 'files' key
    if 'files' not in fixity:
        raise ValueError("Fixity block missing required 'files' key")

    files_list = fixity['files']

    # The 'files' key must be a list
    if not isinstance(files_list, list):
        raise ValueError("'files' key must contain a list")

    # Validate each file reference
    for entry in files_list:
        if isinstance(entry, str):
            file_path = entry
        elif isinstance(entry, dict):
            if 'path' not in entry:
                raise ValueError("File entry dictionary must contain a 'path' key")
            file_path = entry['path']
        else:
            raise ValueError(
                f"Invalid file reference type: {type(entry).__name__}. "
                "Expected a string or a dictionary with a 'path' key."
            )

        if file_path not in manifest_files:
            raise ValueError(f"Fixity block references unknown file: {file_path}")

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"Path does not exist: {path}")
        if os.path.isfile(path):
            return [os.path.abspath(path)]
        if os.path.isdir(path):
            return [os.path.join(path, f) for f in os.listdir(path)
                    if os.path.isfile(os.path.join(path, f))]
        return []
    except Exception:
        return []

def add_asset(self, basename, file_path):
        """
        {
            "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
            "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
            "artigo02-gf03.png": "/path/artigo02-gf03.png",
        }
        """
        if not isinstance(basename, str):
            raise TypeError("basename must be a string")
        if not isinstance(file_path, str):
            raise TypeError("file_path must be a string")
        if not os.path.isdir(file_path):
            raise FileNotFoundError(f"Directory not found: {file_path}")

        extensions = ['.tiff', '.jpg', '.png']
        assets = {}
        for ext in extensions:
            filename = f"{basename}{ext}"
            full_path = os.path.join(file_path, filename)
            if os.path.isfile(full_path):
                assets[filename] = full_path
            else:
                # Optional: warn or skip. Here we raise to enforce presence.
                raise FileNotFoundError(f"Required asset missing: {full_path}")

        return assets

def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not zip_path:
        return {}
    import zipfile
    import os
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                filename = zinfo.filename
                if not filename.lower().endswith('.xml'):
                    continue
                base = os.path.splitext(os.path.basename(filename))[0]
                try:
                    content = zin.read(filename)
                except Exception:
                    continue
                if base in result:
                    result[base].append(content)
                else:
                    result[base] = [content]
    except (FileNotFoundError, zipfile.BadZipFile):
        pass
    return result

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`.
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths or []:
        try:
            result = node.xpath(xpath)
            if result:
                return result[0]
        except Exception:
            continue
    return None

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        package = __package__
        if not package:
            return "unknown"
        try:
            import importlib.metadata as metadata
            return metadata.version(package)
        except Exception:
            # fallback to pkg_resources if metadata isn't available
            try:
                import pkg_resources
                return pkg_resources.get_distribution(package).version
            except Exception:
                return "unknown"
    except Exception:
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters:
        pieces (Iterable): An iterable of version components (strings or
            integers). Each component will be converted to a string.
        style (str): The rendering style. Supported styles are:
            * 'numeric' - joined by '.' (e.g., '1.2.3')
            * 'comma'   - joined by ', ' (e.g., '1, 2, 3')
            * 'json'    - JSON array representation
            * 'plain'   - joined by a single space (e.g., '1 2 3')
            * 'short'   - first two components joined by '.' (e.g., '1.2')

    Returns:
        str: The formatted version string.

    Raises:
        TypeError: If pieces is not an iterable.
        ValueError: If style is unsupported or pieces is empty.
    """
    # Validate pieces
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError(f"pieces must be an iterable, got {type(pieces).__name__}")

    # Convert pieces to strings and collect them
    try:
        component_strs = [str(p) for p in iterator]
    except Exception as exc:
        raise ValueError(f"Error converting version pieces to strings: {exc}")

    if not component_strs:
        raise ValueError("pieces must contain at least one component")

    # Normalize style
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")
    style = style.strip().lower()

    if style == 'numeric':
        return '.'.join(component_strs)
    elif style == 'comma':
        return ', '.join(component_strs)
    elif style == 'plain':
        return ' '.join(component_strs)
    elif style == 'short':
        # Short style uses the first two components, if available
        return '.'.join(component_strs[:2])
    elif style == 'json':
        import json
        return json.dumps(component_strs)
    else:
        raise ValueError(f"Unsupported style '{style}'. "
                         f"Supported styles are: numeric, comma, plain, short, json.")

def plus_or_dot(pieces):
    """Return a '+' if we don't already have one, else return a '.'."""
    try:
        return '.' if '+' in pieces else '+'
    except Exception as exc:
        raise ValueError(f"Invalid input for plus_or_dot: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the list of arguments to run
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        cmd_list = [commands]
    if args:
        if isinstance(args, (list, tuple)):
            cmd_list.extend(args)
        else:
            cmd_list.append(str(args))

    if verbose:
        try:
            # Display the command as a quoted string for clarity
            print("Running command:", " ".join(repr(c) for c in cmd_list))
        except Exception:
            # Fallback if a component cannot be converted to string
            print("Running command:", " ".join(str(c) for c in cmd_list))

    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        output = subprocess.check_output(
            cmd_list,
            cwd=cwd,
            env=env,
            stderr=stderr,
            universal_newlines=True,
        )
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(e.cmd)}' failed with exit code {e.returncode}"
        raise RuntimeError(msg) from e
    except Exception as exc:
        msg = f"Failed to run command '{' '.join(cmd_list)}': {exc}"
        raise RuntimeError(msg) from exc

    return output

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(fn):
        """Store fn in HANDLERS[vcs][method]."""
        global HANDLERS
        if 'HANDLERS' not in globals():
            HANDLERS = {}
        HANDLERS.setdefault(vcs, {})[method] = fn
        return fn
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine how to iterate over objects in the hierarchy.
    # The class is expected to provide an ``_objects`` iterable or method that yields
    # each object in the storage root hierarchy.
    if not hasattr(self, "_objects"):
        raise AttributeError("The object does not provide a '_objects' attribute or method to iterate over hierarchy items.")

    # Counters for results.
    num_objects = 0
    good_objects = 0

    # Helper to log warning messages if a logger is available; otherwise fallback to print.
    def _log_warning(msg):
        logger = getattr(self, "_logger", None)
        if logger and hasattr(logger, "warning"):
            logger.warning(msg)
        else:
            print(f"WARNING: {msg}")

    for obj in self._objects():
        num_objects += 1
        is_valid = True
        try:
            # Validate the object itself if requested.
            if validate_objects:
                # Prefer an explicit validate method if present.
                if hasattr(obj, "validate") and callable(obj.validate):
                    is_valid = obj.validate()
                # Fallback: if object has a 'schema' attribute, use it.
                elif hasattr(obj, "schema") and hasattr(obj, "data"):
                    from schema import Schema, SchemaError  # Imported lazily to avoid dependency at import time.
                    try:
                        Schema(obj.schema).validate(obj.data)
                    except SchemaError:
                        is_valid = False

            # Check digests if requested.
            if check_digests:
                # Expect the object to expose an expected_digest and compute_digest attributes.
                expected = getattr(obj, "expected_digest", None)
                compute = getattr(obj, "compute_digest", None)
                if expected is not None and callable(compute):
                    actual = compute()
                    if actual != expected:
                        is_valid = False
                else:
                    # If we can't compute a digest, skip this check but warn the user.
                    if show_warnings:
                        _log_warning(f"Digest check skipped for {obj} – missing expected_digest or compute_digest")

        except Exception as exc:
            # Any unexpected exception makes the object invalid.
            is_valid = False
            if show_warnings:
                _log_warning(f"Exception while validating {obj}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # ensure there is at least one version directory
    if not version_dirs:
        return self  # nothing to validate

    # dictionary to record differences relative to the root inventory
    self.different_digests = {}

    root_inventory = None
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(
                f"Missing inventory file in version directory: {vdir}"
            )
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except Exception as e:
            raise ValueError(
                f"Failed to read inventory in {vdir}: {e}"
            ) from e

        if root_inventory is None:
            # the first inventory served as the root reference
            root_inventory = inventory
            continue

        # compare this inventory against the root inventory
        diff = {
            name: digest
            for name, digest in inventory.items()
            if root_inventory.get(name) != digest
        }
        if diff:
            self.different_digests.setdefault(vdir, {}).update(diff)

    # Optionally verify that each inventory contains all items present in the root
    for vdir in version_dirs[1:]:
        inv_path = os.path.join(vdir, "inventory.json")
        with open(inv_path, "r", encoding="utf-8") as fh:
            inventory = json.load(fh)
        missing = set(root_inventory.keys()) - inventory.keys()
        if missing:
            raise ValueError(
                f"Inventory in {vdir} is missing items: {', '.join(sorted(missing))}"
            )

    return self

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Validate inputs
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")
    if bug_ids is None:
        return params

    # Normalise bug_ids to a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    elif isinstance(bug_ids, (list, tuple)):
        bug_ids = list(bug_ids)
    else:
        raise ValueError("bug_ids must be a scalar, list, or tuple")

    # Convert all entries to string and strip whitespace
    bug_ids = [str(b).strip() for b in bug_ids if str(b).strip()]

    # Merge into existing 'ids' or create it
    if 'ids' in params:
        # Existing ids may be a string or iterable
        existing = params['ids']
        if isinstance(existing, str):
            existing_ids = [e.strip() for e in existing.split(',') if e.strip()]
        elif isinstance(existing, (list, tuple)):
            existing_ids = [str(e).strip() for e in existing if str(e).strip()]
        else:
            existing_ids = []

        # Combine without duplicates while preserving order
        combined_ids = existing_ids
        for b in bug_ids:
            if b not in combined_ids:
                combined_ids.append(b)

        params['ids'] = ','.join(combined_ids)
    else:
        params['ids'] = ','.join(bug_ids)

    return params

def deep_merge_nodes(nodes):
    '''Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:
...
    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper predicates
    def _is_mapping(node):
        return hasattr(node, 'tag') and node.tag.startswith('tag:yaml.org,2002:map')

    def _is_scalar(node):
        return hasattr(node, 'tag') and node.tag.startswith('tag:yaml.org,2002:str')

    # Recursively merge two mapping nodes (list of key/value tuples)
    def _merge_mapping_lists(list_a, list_b):
        result = {}
        order = []

        for key_node, val_node in list_a:
            key = key_node.value
            result[key] = (key_node, val_node)
            order.append(key)

        for key_node, val_node in list_b:
            key = key_node.value
            if key in result:
                existing_key_node, existing_val_node = result[key]
                merged_val = _merge_values(existing_val_node, val_node)
                result[key] = (existing_key_node, merged_val)
            else:
                result[key] = (key_node, val_node)
                order.append(key)

        return [result[k] for k in order]

    # Merge two node values
    def _merge_values(v1, v2):
        # If v2 is a mapping node, it wins
        if _is_mapping(v2):
            if _is_mapping(v1):
                merged_pairs = _merge_mapping_lists(v1.value, v2.value)
                return type(v2)(v2.tag, merged_pairs)
            else:
                return v2
        else:
            return v2  # v2 non‑mapping overrides v1

    merged_map = {}
    for key_node, val_node in nodes:
        if not _is_scalar(key_node):
            # Skip entries that do not have a proper scalar key
            continue
        key = key_node.value
        if key in merged_map:
            existing_key_node, existing_val_node = merged_map[key]
            merged_val = _merge_values(existing_val_node, val_node)
            merged_map[key] = (existing_key_node, merged_val)
        else:
            merged_map[key] = (key_node, val_node)

    return list(merged_map.values())

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    parser = argparse.ArgumentParser(description='Command-line argument parser')
    try:
        if arguments:
            # Flatten nested lists or tuples that may be passed
            flat_args = []
            for arg in arguments:
                if isinstance(arg, (list, tuple)):
                    flat_args.extend(arg)
                else:
                    flat_args.append(arg)
            return parser.parse_args(flat_args)
        else:
            return parser.parse_args()
    except SystemExit as e:
        # argparse raises SystemExit on parse error; convert to ValueError for caller
        raise ValueError(f"Argument parsing failed: {e}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error during argument parsing: {e}") from e

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        if parser is None:
            return ''
        flags = set()
        for action in parser._actions:
            for opt in getattr(action, 'option_strings', []):
                if opt:
                    flags.add(opt)
        return ' '.join(sorted(flags))
    except Exception:
        return ''

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    import sys

    # Combine any iterable arguments into a flat list
    if len(arguments) == 1 and isinstance(arguments[0], (list, tuple, set)):
        args = list(arguments[0])
    else:
        args = list(arguments)

    # If no arguments were supplied, use sys.argv[1:]
    if not args:
        args = sys.argv[1:]

    parser = argparse.ArgumentParser()
    try:
        return parser.parse_args(args)
    except SystemExit as e:
        # argparse uses SystemExit to indicate parsing failure or help request
        raise ValueError('Argument parsing failed') from e

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
        return ""
    flags = []
    for action in getattr(parser, '_actions', []):
        # Some actions may have no option strings (e.g., positional arguments)
        for flag in getattr(action, 'option_strings', []):
            flags.append(flag)
    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    # Handle the case where no arguments are supplied
    if not unparsed_arguments:
        args = []
    else:
        # Flatten the tuple into a list of arguments
        args = list(unparsed_arguments[0]) if len(unparsed_arguments) == 1 else list(unparsed_arguments)

    # Create a top-level parser
    parser = argparse.ArgumentParser(add_help=False)  # Assume help is handled elsewhere
    # Set up subparsers with a destination attribute
    subparsers = parser.add_subparsers(dest="subcommand")
    # NOTE: Subparser configurations should be added here if known.
    # For this generic helper, we simply preserve the ability to parse subcommands.

    try:
        # Parse the known arguments; args not recognized will cause an error (unlike parse_known_args)
        namespace = parser.parse_args(args)
    except SystemExit as exc:
        # argparse uses SystemExit to indicate parsing failure
        raise ValueError(f"Failed to parse arguments: {exc}") from None

    sub_name = getattr(namespace, "subcommand", None)

    if sub_name:
        # The user invoked a subcommand; return a mapping keyed by that name
        return {sub_name: namespace}
    else:
        # No subcommand was supplied; return the global namespace
        return {"global": namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")

    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict of subparser name -> ArgumentParser instances")

    parsed_namespaces = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(list(unparsed_arguments))
        except Exception:
            # If parsing fails for this subparser, skip it but record no unknowns
            unknown = list(unparsed_arguments)
            namespace = None
        parsed_namespaces[name] = namespace
        unknown_sets.append(set(unknown))

    # Determine remaining arguments not claimed by any subparser
    if unknown_sets:
        # Keep args that were unknown for every subparser
        remaining = [arg for arg in unparsed_arguments if all(arg in uset for uset in unknown_sets)]
    else:
        remaining = list(unparsed_arguments)

    return parsed_namespaces, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be greater than 0")
    for i in range(0, len(response), max_results):
        yield response[i:i+max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    # Ensure we have an iterable of dicts; if a single dict is passed, wrap it in a list
    if isinstance(dicts, dict):
        dicts = [dicts]
    # Guard against non-iterable input
    try:
        iter(dicts)
    except TypeError as exc:
        raise TypeError("Input must be an iterable of dictionaries") from exc

    from collections import Counter
    from functools import reduce

    # Convert each dictionary into a Counter and sum them
    try:
        counters = [Counter(d) for d in dicts if d]
        # Sum all counters; start with an empty Counter
        total = reduce(operator.add, counters, Counter())
    except Exception as exc:
        # Raise a more informative error if value types cannot be summed
        raise TypeError("All values must support addition (e.g., integers or floats)") from exc

    return dict(total) if total else {}

