def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    def _rename_key(obj, old_key, new_key):
        if isinstance(obj, dict):
            if old_key in obj:
                # avoid overwriting existing key
                if new_key in obj:
                    raise KeyError(
                        f"Cannot rename key '{old_key}' to '{new_key}': "
                        f"target key already exists in this dictionary."
                    )
                obj[new_key] = obj.pop(old_key)
            # recurse into sub‑objects
            for v in obj.values():
                _rename_key(v, old_key, new_key)
        elif isinstance(obj, list):
            for item in obj:
                _rename_key(item, old_key, new_key)
        # other types are ignored

    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, str):
        raise TypeError("register_number must be a string")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    _rename_key(flow_params, register_value, register_number)
    return flow_params

