def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type, got %r" % cls)
    seen = set()
    queue = [cls]
    while queue:
        parent = queue.pop()
        try:
            children = parent.__subclasses__()
        except Exception:
            continue
        for child in children:
            if child not in seen:
                seen.add(child)
                queue.append(child)
    seen.discard(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")
    base = len(alphabet)
    # Build mapping from character to its numeric value
    try:
        char_to_value = {char: i for i, char in enumerate(alphabet)}
    except Exception as e:
        raise ValueError(f"Failed to build alphabet mapping: {e}") from e

    num = 0
    for char in string:
        if char not in char_to_value:
            raise ValueError(f"Character '{char}' not found in alphabet")
        num = num * base + char_to_value[char]
    return num

def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Ensure destination_path is a Path instance
    if not isinstance(destination_path, Path):
        destination_path = Path(destination_path)

    # Destination must not exist or be empty
    if destination_path.exists():
        if not destination_path.is_dir():
            raise OSError(f"Destination path {destination_path} exists and is not a directory")
        # Allow extraction into empty directory only
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory {destination_path} is not empty")

    else:
        # Create directory
        try:
            destination_path.mkdir(parents=True, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Unable to create destination directory {destination_path}") from exc

    # Download the archive to a temporary file
    import tempfile
    import shutil

    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp_file:
            temp_path = Path(tmp_file.name)
            try:
                resp = requests.get(url, stream=True, timeout=30)
                resp.raise_for_status()
            except requests.RequestException as exc:
                raise RuntimeError(f"Failed to download archive from {url}") from exc

            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)

        # Extract the archive
        try:
            with tarfile.open(temp_path, mode="r:gz") as tar:
                tar.extractall(path=destination_path)
        except tarfile.TarError as exc:
            raise RuntimeError(f"Failed to extract archive {temp_path}") from exc

    finally:
        # Clean up temp file
        if temp_path and temp_path.exists():
            try:
                temp_path.unlink()
            except OSError:
                pass

    return destination_path

