def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if host is None:
        return False

    host_str = str(host).strip()

    # Direct string check for the canonical name
    if host_str.lower() == "localhost":
        return True

    try:
        addrinfo = socket.getaddrinfo(host_str, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addrinfo:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == "127.0.0.1":
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            if ip == "::1":
                return True

    return False

