    '''
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    '''
    try:
        if os.path.isfile(config_filename):
            if not overwrite:
                return
    except OSError:
        # If file check fails, treat as non-existent and continue
        pass

    dirpath = os.path.dirname(config_filename)
    if dirpath:
        try:
            os.makedirs(dirpath, exist_ok=True)
        except OSError:
            if not os.path.isdir(dirpath):
                raise

    try:
        with open(config_filename, 'w') as f:
            f.write(rendered_config)
        os.chmod(config_filename, mode)
    except OSError as exc:
        raise

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern

    If pattern is a string, it will be compiled into a regular expression.
    Leading and trailing whitespace will be stripped if ``strip`` is True.
    If pattern is already a compiled regular expression, it is returned unchanged.
    Raises a TypeError for unsupported pattern types.
    """
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # Determine the compiled regex type (Python 3.7+ or earlier)
    try:
        pattern_type = re.Pattern
    except AttributeError:
        pattern_type = type(re.compile(''))
    if isinstance(pattern, pattern_type):
        return pattern
    raise TypeError(f"Unsupported pattern type: {type(pattern).__name__}")

