def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    else:
        roots = set(roots)

    # Verify that the graph object supports triples iteration
    if not hasattr(graph, "triples"):
        raise TypeError("graph must provide a 'triples' method for iterating triples")

    try:
        subjects = set()
        objects = set()
        for s, p, o in graph.triples((None, prop, None)):
            subjects.add(s)
            objects.add(o)

        # A root is a subject that never appears as a parent (object) in any triple
        for s in subjects:
            if s not in objects:
                roots.add(s)
    except Exception as e:
        raise RuntimeError(f"Failed to compute roots: {e}") from e

    return roots

