def fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if dt is None:
        raise ValueError("dt cannot be None")
    if not isinstance(dt, datetime.datetime):
        raise TypeError("dt must be a datetime object")
    if dt.tzinfo is None:
        raise ValueError("dt must be timezone-aware")

    # The target timezone should be stored on the instance, e.g. self.tz
    try:
        target_tz = self.tz
    except AttributeError:
        raise AttributeError("instance has no 'tz' attribute to convert to")

    # Preserve the fold attribute if present (Python 3.6+)
    fold = getattr(dt, "fold", 0)
    try:
        new_dt = dt.astimezone(target_tz)
    except Exception as exc:
        raise RuntimeError(f"Failed to convert datetime to target timezone: {exc}") from exc

    # Ensure the fold status is carried over to the new datetime
    if hasattr(new_dt, "replace"):
        try:
            new_dt = new_dt.replace(fold=fold)
        except TypeError:
            # Some tzinfo objects may not support 'fold'; ignore if so
            pass

    return new_dt

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Try private encrypted JSON payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body = body.decode()
        data = json.loads(body)
        if isinstance(data, dict) and "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Try public XML payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body = body.decode()
        xml_root = etree.fromstring(body.encode() if isinstance(body, str) else body)
        if xml_root.tag == "MAGIC_ENV_TAG":
            return True
    except Exception:
        pass

    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request."""
    # Defensive check for a None request
    if request is None:
        return False

    # Attempt to read the path. Django uses request.path, Flask uses request.path.
    path = getattr(request, "path", None)
    if path is None:
        # Some older frameworks may expose the raw URI as REQUEST_URI
        path = getattr(request, "REQUEST_URI", None)

    # Check common Matrix URL prefix
    if isinstance(path, str) and path.startswith("/_matrix"):
        return True

    # Check for Matrix‑specific content type (many Matrix endpoints use JSON)
    meta = getattr(request, "META", None)
    if meta and isinstance(meta, dict):
        content_type = meta.get("CONTENT_TYPE") or meta.get("content-type")
        if isinstance(content_type, str) and content_type.startswith("application/json"):
            return True

        # Some Matrix servers may set a custom header
        if "x-matrix" in meta or "X-Matrix" in meta:
            return True

    # As a fallback, inspect request headers if available
    headers = getattr(request, "headers", None)
    if headers:
        # Request.headers can be a dict‑like object
        for key in ("Content-Type", "content-type", "X-Matrix", "x-matrix"):
            if key in headers:
                value = headers[key]
                if isinstance(value, str) and value.startswith("application/json"):
                    return True
                if key.lower() == "x-matrix":
                    return True

    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    from datetime import datetime, timezone
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime instance")
    if dt.tzinfo is None:
        # Assume the naive datetime is already in UTC
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        # Convert to UTC for consistency
        dt = dt.astimezone(timezone.utc)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    # Regular expression to match typical URLs or file references.
    url_re = re.compile(
        r'\b((?:https?://|www\.)\S+|(?:[\w\.-]+\/[\w\.-]+\.\w{1,4})|\b\w+:\w+)\b',
        re.IGNORECASE,
    )

    def replace_link(match):
        url = match.group(1)

        # Normalise URLs starting with 'www.'
        href = url if url.startswith(('http://', 'https://')) else f'http://{url}'

        # Build the <a> tag with safety attributes.
        return (
            f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'
        )

    # Substitute all matched URLs with enriched link tags.
    return url_re.sub(replace_link, text)

def fetch_content_type(url: str) -> Optional[str]:
        """Fetch the HEAD of the remote url to determine the content type."""
        try:
            scheme, netloc, _, _, _ = urlsplit(url)
            if scheme.lower() not in ('http', 'https', 'ftp', 'ftps'):
                return None
            req = Request(url, method='HEAD')
            with urlopen(req) as resp:
                # Accept 200‑300 status codes; otherwise ignore
                status = getattr(resp, "status", getattr(resp, "getcode", lambda: 0)())
                if status and status < 200 or status >= 400:
                    return None
                return resp.headers.get("Content-Type")
        except Exception:
            return None

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    # Safeguard against None or non-iterable input
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception:
        return {}
    result = {}
    for child in children:
        key = child.tag
        # Normalise namespace if present
        if '}' in key:
            key = key.split('}', 1)[1]
        if key in result:
            existing = result[key]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[key] = [existing, child]
        else:
            result[key] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    from urllib.parse import urlparse

    # Basic input validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")

    try:
        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https"):
            raise ValueError("url must start with http:// or https://")
    except Exception as exc:
        raise ValueError(f"Invalid url '{url}'") from exc

    # Canonicalise base url (ensure no trailing slash)
    base_url = url.rstrip("/")

    # Determine location of the nodeinfo endpoint
    nodeinfo_href = document_path if document_path else f"{base_url}/.well-known/nodeinfo"

    # Build the .well-known/nodeinfo JSON structure
    result = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": nodeinfo_href
            }
        ]
    }

    return result

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}

    import json
    from xml.etree import ElementTree as ET

    # Try JSON parsing first
    try:
        data = json.loads(document)
        # If the JSON already contains the hcard_url, keep it; otherwise try to derive one
        if isinstance(data, dict) and "hcard_url" not in data:
            # Attempt to find a link with rel containing 'profile' or 'hcard'
            links = data.get("links", [])
            for link in links:
                rel = link.get("rel", "").lower()
                if "profile" in rel or "hcard" in rel:
                    # Replace placeholder {uri} if present
                    template = link.get("template")
                    href = link.get("href")
                    if template:
                        data["hcard_url"] = template.replace("{uri}", "")
                    elif href:
                        data["hcard_url"] = href
                    break
        return data
    except Exception:
        pass  # Not JSON, fall back to XRD

    # Parse XRD (XML)
    try:
        root = ET.fromstring(document)
    except ET.ParseError:
        return {}

    ns = {"xrd": "xri://$xrd*($v*2.0)"}
    subject = root.find("xrd:Subject", ns)
    aliases = root.findall("xrd:Alias", ns)

    result = {}
    if subject is not None and subject.text:
        result["subject"] = subject.text

    if aliases:
        result["aliases"] = [a.text for a in aliases if a.text]

    links = []
    for link in root.findall("xrd:Link", ns):
        rel = link.get("rel")
        href = link.get("href")
        template = link.get("template")
        link_dict = {}
        if rel:
            link_dict["rel"] = rel
        if href:
            link_dict["href"] = href
        if template:
            link_dict["template"] = template
        if link_dict:
            links.append(link_dict)
    if links:
        result["links"] = links

    # Attempt to derive an hcard_url
    hcard_url = None
    for link in links:
        rel = link.get("rel", "").lower()
        if "profile" in rel or "hcard" in rel:
            if "template" in link:
                hcard_url = link["template"].replace("{uri}", "")
            else:
                hcard_url = link.get("href")
            break
    if hcard_url:
        result["hcard_url"] = hcard_url

    return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        try:
            logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        except NameError:
            pass
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle)
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    link = hostmeta.find_link(rels="lrdd")
    if not link:
        return None
    url = link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Normalize settings_dirs to a list of directory paths
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif settings_dirs is None:
        dirs = []
    else:
        try:
            dirs = list(settings_dirs)
        except TypeError:
            dirs = [settings_dirs]

    # Determine file matching logic based on spec_option
    if isinstance(spec_option, (list, tuple)):
        def check_file(name):
            return any(name.endswith(ext) for ext in spec_option)
    else:
        def check_file(name):
            return name.endswith(spec_option) if spec_option else True

    matched_paths = []
    for directory in dirs:
        try:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if check_file(fname):
                    matched_paths.append(os.path.join(directory, fname))
        except OSError:
            continue

    # Return a sorted list of fully qualified filenames
    return sorted(matched_paths)

def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        # Attempt to lazily import and instantiate the Ansible config manager,
        # caching it on the class for subsequent calls.  If the import
        # fails, raise a clear RuntimeError to aid debugging.
        if not hasattr(cls, "_ansible_config_manager"):
            try:
                from ansible.config.manager import ConfigManager
            except ImportError as exc:
                raise RuntimeError(
                    "Failed to import ansible.config.manager; "
                    "ensure ansible is installed and importable."
                ) from exc
            try:
                cls._ansible_config_manager = ConfigManager()
            except Exception as exc:
                raise RuntimeError(
                    "Error creating ansible config manager instance."
                ) from exc
        return cls._ansible_config_manager

def workspace_manager(cls):
    """Gets the workspace manager. """
    try:
        return cls._workspace_manager
    except AttributeError:
        raise AttributeError("Workspace manager not defined on class")

def plugins_manager(cls):
    """Gets the plugin manager. """
    manager = getattr(cls, "_plugins_manager", None)
    if manager is None:
        try:
            manager = PluginManager()
        except Exception as exc:
            raise RuntimeError(f"Failed to instantiate plugin manager: {exc}") from exc
        setattr(cls, "_plugins_manager", manager)
    return manager

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")
        # Parse YAML if the content is a string/bytes; assume dict otherwise
        if isinstance(spec_content, (dict,)):
            spec_dict = spec_content
        else:
            try:
                spec_dict = yaml.safe_load(spec_content)
            except Exception as e:
                raise IRValidatorException(f"Failed to parse spec content: {e}")
        if not isinstance(spec_dict, dict):
            raise IRValidatorException("Spec content must be a mapping after parsing")
        # Define mandatory fields and check their presence
        required_fields = ['kind', 'metadata', 'spec']
        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")
        return spec_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Merge defaults from the default spec if present
    try:
        default_spec = getattr(self, "_default_spec", None)
        if default_spec:
            to_dict = getattr(default_spec, "to_dict", None)
            if to_dict:
                defaults.update(to_dict())
    except Exception:
        pass

    # Merge values from the main spec, overriding defaults
    try:
        spec = getattr(self, "spec", None)
        if spec:
            to_dict = getattr(spec, "to_dict", None)
            if to_dict:
                defaults.update(to_dict())
    except Exception:
        pass

    # Ensure any option that has an inherent default value is included,
    # unless already overridden by the specs above.
    for arg in getattr(self, "args", []):
        if hasattr(arg, "name") and hasattr(arg, "default"):
            if arg.name not in defaults and not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    # Mapping of deprecated keyword arguments to the current preferred names.
    # Extend this dictionary as new deprecations are introduced.
    return {
        "old_option": "new_option",
        "legacy_flag": "modern_flag",
        "deprecated_mode": "mode",
    }

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # If no arguments were supplied, return an empty list
    if args is None:
        return []

    silent = []

    # Handle mapping types (e.g., dict of argument name to value)
    if isinstance(args, dict):
        # Arguments whose value evaluates to False (None, False, 0, empty string/collection) are considered silent
        silent = [key for key, value in args.items() if not value]

    # Handle list or tuple of items
    elif isinstance(args, (list, tuple)):
        # If each item is a (name, value) pair, treat similar to dict
        if all(isinstance(item, (tuple, list)) and len(item) == 2 for item in args):
            silent = [name for name, val in args if not val]
        # If the list contains only strings and they are falsy (e.g., empty strings), treat them as silent
        elif all(isinstance(item, str) for item in args):
            silent = [name for name in args if not name]

    # For any other type, attempt to iterate if possible
    else:
        try:
            for item in args:
                # If item is a tuple, use the first element as the name
                if isinstance(item, (tuple, list)) and len(item) == 2:
                    name, value = item
                    if not value:
                        silent.append(name)
                else:
                    # For non-tuple items, include if the item itself is falsy
                    if not item:
                        silent.append(item)
        except TypeError:
            # arg not iterable; return empty list
            silent = []

    return silent

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    # Ensure that the class defines a `required_args` attribute
    try:
        required = getattr(self, 'required_args')
    except AttributeError:
        raise AttributeError("The object does not have a 'required_args' attribute.")
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("'required_args' must be a list, tuple, or set.")
    # Validate input type
    if not isinstance(args, dict):
        raise TypeError("'args' must be a mapping (dict).")
    # Find missing required arguments
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []

    # Normalise the spec container to an iterable of (key, spec) pairs
    if isinstance(options_spec, dict):
        spec_iter = options_spec.items()
    else:
        # Assume an iterable of spec dictionaries or (key, spec) tuples
        spec_iter = []
        for item in options_spec:
            if isinstance(item, dict):
                # Try to extract key from item if present
                key = item.get('arg') or item.get('name')
                spec_iter.append((key, item))
            elif isinstance(item, tuple) and len(item) == 2:
                spec_iter.append(item)
            else:
                # Skip items that are not recognizable
                continue

    for key, spec in spec_iter:
        if not isinstance(spec, dict):
            continue
        cond = spec.get('required_when')
        if cond is None:
            continue
        # Evaluate the condition; support plain bool or callable
        if callable(cond):
            try:
                # Prefer passing command_name and args
                match = cond(command_name, args)
            except TypeError:
                try:
                    match = cond(args)
                except TypeError:
                    try:
                        match = cond()
                    except Exception:
                        # If the condition cannot be called, treat as False
                        match = False
        else:
            match = bool(cond)
        if match:
            # Build argument name: prefer explicit 'arg', fallback to key
            name = spec.get('arg') or spec.get('name') or key
            if name:
                required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from the parsed YAML
    arg_specs = self.parsed_yaml.get('args', {})
    if not isinstance(arg_specs, dict):
        # No specifications to validate against
        return

    # Normalise the received arguments into a dictionary for easy lookup
    try:
        if isinstance(args, dict):
            received = args
        elif isinstance(args, list):
            received = {}
            for item in args:
                if isinstance(item, dict):
                    for k, v in item.items():
                        received[k] = v
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    received[item[0]] = item[1]
                else:
                    # Skip items that cannot be interpreted as key/value pairs
                    continue
        else:
            raise TypeError("args must be a dict or a list of key/value pairs")
    except Exception as exc:
        raise ValueError(f"Error normalising arguments: {exc}") from exc

    # Validate each argument that has a 'length' constraint
    for name, spec in arg_specs.items():
        # Skip specifications that are not dictionaries
        if not isinstance(spec, dict):
            continue
        maxlen = spec.get('length')
        if maxlen is None:
            continue  # no length constraint specified
        if name not in received:
            continue  # argument not supplied; default handling elsewhere

        val = received[name]
        try:
            val_len = len(val)
        except Exception as exc:
            raise TypeError(f"Argument '{name}' does not have a length attribute") from exc

        if val_len > maxlen:
            raise ValueError(
                f"Argument '{name}' too long: {val_len} > {maxlen}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is iterable
    try:
        args = tuple(args)
    except Exception:
        raise TypeError("args must be an iterable of at least three elements")

    if len(args) < 3:
        raise TypeError(
            f"expected at least three arguments (value, minimum, maximum), got {len(args)}"
        )

    value, minimum, maximum = args[0], args[1], args[2]

    # Check that minimum and maximum are not None
    if minimum is None or maximum is None:
        raise ValueError("minimum and maximum must not be None")

    # Check that minimum <= maximum
    try:
        if minimum > maximum:
            raise ValueError(
                f"maximum ({maximum}) must be greater or equal to minimum ({minimum})"
            )
    except TypeError as exc:
        raise TypeError(
            "minimum and maximum must be comparable types"
        ) from exc

    # Validate the value
    if value is None:
        raise ValueError("value must not be None")

    try:
        if value < minimum or value > maximum:
            raise ValueError(
                f"expected value between {minimum} and {maximum}, got {value}"
            )
    except TypeError as exc:
        raise TypeError(
            "value, minimum, and maximum must be comparable types"
        ) from exc

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # If a mapping with a fully‑qualified type is supplied, delegate to the
    # existing `construct` helper which knows how to instantiate the object.
    if isinstance(spec_option, dict) and "__type__" in spec_option:
        try:
            return self.construct(spec_option)
        except Exception as exc:
            raise ValueError(
                f"Unable to construct complex type '{type_name}' for "
                f"option '{option_name}': {exc}"
            ) from exc

    # If `spec_option` is already a callable factory, call it with the option name
    if callable(spec_option):
        try:
            return spec_option(option_name=option_name, subcommand=subcommand)
        except Exception as exc:
            raise ValueError(
                f"Error while calling factory for complex type '{type_name}' "
                f"of option '{option_name}': {exc}"
            ) from exc

    # If `spec_option` is a string, treat it as a key into the subcommand's
    # registry of complex types, if one exists.
    if isinstance(spec_option, str):
        registry = getattr(subcommand, "complex_type_registry", {})
        factory = registry.get(spec_option)
        if factory is None:
            raise KeyError(
                f"Complex type '{spec_option}' is not registered for subcommand "
                f"'{subcommand!r}' when resolving option '{option_name}'."
            )
        try:
            return factory()
        except Exception as exc:
            raise ValueError(
                f"Error constructing complex type '{spec_option}' for option "
                f"'{option_name}': {exc}"
            ) from exc

    # As a last resort, return the value wrapped in a list to keep a
    # consistent return type for callers expecting an iterable of types.
    return [spec_option]

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        if args is None:
            return control_args, nested_args

        try:
            # Accept either a dict or an iterable of (key, value) pairs
            if hasattr(args, 'items'):
                iterator = args.items()
            else:
                iterator = args

            for key, value in iterator:
                if isinstance(key, str) and key.startswith("control_"):
                    # Strip prefix and add to control args
                    control_args[key[len("control_"):]] = value
                elif isinstance(key, str) and key.startswith("custom_"):
                    # Strip prefix and add to nested args
                    nested_args[key[len("custom_"):]] = value
                else:
                    nested_args[key] = value
        except Exception as exc:
            # Re-raise with context for debugging
            raise ValueError(f"Error processing arguments: {exc}") from exc

        return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Ensure vars_dict is a dictionary; if None, treat as empty dict
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary or None")

    # If no extra_vars provided, simply return the existing dictionary
    if not extra_vars:
        return vars_dict

    # Validate that extra_vars is a list
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list of dictionaries or None")

    # Merge each dictionary in the extra_vars list into vars_dict
    for extra in extra_vars:
        if not isinstance(extra, dict):
            raise TypeError("each element of extra_vars must be a dictionary")
        vars_dict.update(extra)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build base command
    command = ["ansible-playbook"]

    # Verbosity
    if verbose:
        if isinstance(verbose, int):
            command.append("-" + "v" * verbose)
        else:
            command.append(f"-{verbose}")

    # Additional ansible-playbook arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    command.append(f"--{key}")
            elif value is None:
                command.append(f"--{key}")
            else:
                command.extend([f"--{key}", str(value)])

    # Extra vars
    if extra_vars:
        command.append("--extra-vars")
        command.append(" ".join([f"{k}={v}" for k, v in extra_vars.items()]))

    # Append playbook path
    command.append(playbook_path)

    _debug("Executing Ansible call: %s", " ".join(command))
    try:
        p = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        stdout, stderr = p.communicate()
        if p.returncode != 0:
            raise RuntimeError(f"ansible-playbook reported an error: {stderr.strip()}")
        return stdout
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Guard against invalid input
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")

    # Retrieve the option definitions for the given parser
    try:
        options = self[parser_name]
    except TypeError:
        # self might not be subscriptable; treat as empty
        options = []
    except KeyError:
        # No parser with that name; nothing to convert
        return

    for opt in options:
        name = getattr(opt, "name", None)
        if name is None:
            continue

        if name not in values_dict:
            continue

        raw_value = values_dict[name]
        # Attempt to convert the raw string to the expected type
        try:
            if hasattr(opt, "convert") and callable(opt.convert):
                converted = opt.convert(raw_value)
            elif hasattr(opt, "type"):
                # opt.type may be a callable (e.g., int, float, bool)
                converted = opt.type(raw_value)
            else:
                # No conversion information; keep as is
                converted = raw_value
        except Exception:
            # If conversion fails, retain the original value
            converted = raw_value

        values_dict[name] = converted

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # try importing yaml; fall back if not available
    try:
        import yaml
    except Exception:  # pragma: no cover
        yaml = None

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' not found or is not a directory.")

    # Determine spec file (prefer json, fallback to yaml)
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.exists(candidate):
            spec_path = candidate
            break
    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of "
                                f"'plugin.json', 'plugin.yaml', or 'plugin.yml'.")

    # Load spec content
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            try:
                spec_data = json.load(f)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Failed to parse JSON spec at '{spec_path}': {exc}") from exc
        else:
            if yaml is None:
                raise ImportError("PyYAML is required to parse YAML plugin specs.")
            try:
                spec_data = yaml.safe_load(f)
            except yaml.YAMLError as exc:
                raise ValueError(f"Failed to parse YAML spec at '{spec_path}': {exc}") from exc

    if not isinstance(spec_data, dict):
        raise TypeError(f"The plugin spec at '{spec_path}' must be a mapping/dictionary.")

    # Flatten helper
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    # Determine the environment variable name and config path
    try:
        env_var = getattr(self, 'config_env_var', 'CONFIG_PATH')
        config_path = getattr(self, 'config_path')
    except AttributeError as exc:
        raise RuntimeError(
            "Missing attribute required for injecting config (config_env_var or config_path)"
        ) from exc

    if not env_var or config_path is None:
        # Nothing to set
        return

    # Convert the config path to a string if it's a pathlib.Path or similar
    config_value = str(config_path)

    # Set the environment variable only if it is not already defined
    try:
        if env_var not in os.environ:
            os.environ[env_var] = config_value
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(
            f"Failed to set environment variable '{env_var}' to '{config_value}'"
        ) from exc

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if root_subparsers is None:
        raise ValueError('root_subparsers cannot be None')
    try:
        root_subparsers.add_argument(
            '-s', '--spec',
            dest='spec',
            help='Target address spec or path, e.g., path/to/file:target'
        )
    except Exception as exc:
        raise RuntimeError(f'Failed to add spec option to CLI: {exc}') from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("root must be a non-empty path")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    abs_path = os.path.abspath(norm_path)
    abs_root = os.path.abspath(norm_root)
    try:
        rel_path = os.path.relpath(abs_path, abs_root)
    except ValueError:
        raise ValueError("Root '{0}' is not a prefix of path '{1}'".format(root, path))
    if rel_path == os.curdir:
        return ''
    return rel_path
